package com.wipro.hibernate;import org.hibernate.*;import java.util.*;public class Main{public static void main(String[]a){try(Session s=HibernateUtil.getSessionFactory().openSession()){Transaction t=s.beginTransaction();List<CarDetail>c=List.of(new CarDetail("M-01","Polo","White","Volkswagen"),new CarDetail("M-02","Vento","Black","Volkswagen"));s.persist(new MultiCarOwner(1,"Meenakshi",new ArrayList<>(c)));t.commit();System.out.println("One-to-many owner/cars persisted.");}HibernateUtil.getSessionFactory().close();}}